mapper.select:
SELECT a.ID AS value,REPLACE(a.index_name,'告警次数','') AS label
FROM `system_docking`.api_platform_index_info a
LEFT JOIN `system_docking`.api_interface_system_platform_info b ON a.platform_id=b.ID
LEFT JOIN `system_docking`.api_interface_system_info c ON b.system_id=c.ID
WHERE a.is_enable='1' AND b.is_enable='1' AND c.is_enable='1'

    AND a.index_type=#{params.isStatus}


    AND a.is_monitor=#{params.is_monitor}


    AND c.system_code=#{params.systemType}

select.if:
SELECT a.ID AS value,CONCAT(a.resource_desc,'(',f.ip_address,')') AS label FROM `system_docking`.api_system_resource a LEFT JOIN `system_docking`.api_system_index_resource b ON a.ID=b.resource_id LEFT JOIN `system_docking`.api_platform_index_info c ON b.index_id=c.ID LEFT JOIN `system_docking`.api_interface_system_platform_info d ON c.platform_id=d.ID LEFT JOIN `system_docking`.api_interface_system_info e ON d.system_id=e.ID LEFT JOIN `system_docking`.api_system_resource_ip f ON a.ID=f.resource_id WHERE a.is_enable='1' AND c.is_enable='1' AND d.is_enable='1' AND e.is_enable='1'
AND c.ID=#{params.indicators}
AND e.system_code = #{params.systemType}
GROUP BY a.ID,label ORDER BY label

SELECT a.resource_code AS value,a.resource_desc AS label FROM `system_docking`.api_system_resource a LEFT JOIN `system_docking`.api_interface_system_platform_info b ON a.platform_id=b.ID LEFT JOIN `system_docking`.api_platform_index_info c ON b.ID=c.platform_id LEFT JOIN `system_docking`.api_interface_system_info d ON b.system_id=d.ID WHERE a.is_enable='1' AND b.is_enable='1' AND d.is_enable='1'
AND c.ID=#{params.indicators}
AND d.system_code = #{params.systemType}
GROUP BY a.ID,label ORDER BY label

mapper.select:
SELECT a.alarm_time,a.index_name,a.resource_name,FORMAT(a.forecast_value,2) AS forecast_value,FORMAT(a.actual_value,2) AS actual_value,FORMAT(a.error_value,2) AS error_value
FROM ${params.dataBase}.api_forecast_alarm_records a
WHERE 1=1

    AND a.is_shared = #{params.is_shared}


    AND a.alarm_time = #{params.time}

ORDER BY CAST(a.error_value AS DECIMAL) DESC

    LIMIT ${params.limit}
